From 7aa90cb1639d9cea99251d7a53d626b2c2f6c695 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:36:29 +0100
Subject: [PATCH] applets/taskmanager: separate desktops when sorting tasks by
 desktop

When tasks from all desktops were shown sorted by desktop, nothing showed
where one desktop's tasks ended and the next began. Now a small gap with
a separator line is added between tasks that belong to different desktops.

BUG: 410453
---
 applets/taskmanager/qml/Task.qml | 44 ++++++++++++++++++++++++++++++++
 1 file changed, 44 insertions(+)

diff --git a/applets/taskmanager/qml/Task.qml b/applets/taskmanager/qml/Task.qml
index 90530078c5..c6bfe50d29 100644
--- a/applets/taskmanager/qml/Task.qml
+++ b/applets/taskmanager/qml/Task.qml
@@ -46,6 +46,8 @@ PlasmaCore.ToolTipArea {
         ? -1
         : ((model.IsLauncher && !tasksRoot.iconsOnly) ? tasksRoot.height / taskList.rows : TaskManagerApplet.LayoutMetrics.preferredMaxWidth())
     Layout.maximumHeight: tasksRoot.vertical ? TaskManagerApplet.LayoutMetrics.preferredMaxHeight() : -1
+    Layout.leftMargin: showDesktopSeparator && !tasksRoot.vertical ? Kirigami.Units.largeSpacing : 0
+    Layout.topMargin: showDesktopSeparator && tasksRoot.vertical ? Kirigami.Units.largeSpacing : 0

     required property var model
     required property int index
@@ -79,6 +81,32 @@ PlasmaCore.ToolTipArea {
         || (task.contextMenu && task.contextMenu.status === PlasmaExtras.Menu.Open)
         || (!!tasksRoot.groupDialog && tasksRoot.groupDialog.visualParent === task)

+    // The virtual desktop this task is sorted under when sorting by desktop
+    readonly property string sortingDesktop: {
+        if (model.IsLauncher || model.IsStartup) {
+            return "";
+        }
+        if (model.IsOnAllVirtualDesktops) {
+            return "all";
+        }
+        const desktops = (model.VirtualDesktops ?? []).map(desktop => String(desktop));
+        return virtualDesktopInfo.desktopIds.map(desktop => String(desktop)).find(desktop => desktops.includes(desktop)) ?? "";
+    }
+    readonly property bool showDesktopSeparator: {
+        if (inPopup || index < 1 || taskRepeater.count < 2
+            || tasksModel.sortMode !== TaskManager.TasksModel.SortVirtualDesktop
+            || Plasmoid.configuration.showOnlyCurrentDesktop
+            || virtualDesktopInfo.numberOfDesktops < 2
+            || sortingDesktop === "") {
+            return false;
+        }
+        const previousTask = taskRepeater.itemAt(index - 1) as Task;
+        return previousTask !== null
+            && previousTask.sortingDesktop !== ""
+            && previousTask.sortingDesktop !== sortingDesktop
+            && (tasksRoot.vertical ? previousTask.x === x : previousTask.y === y);
+    }
+
     active: !inPopup && !tasksRoot.groupDialog && task.contextMenu?.status !== PlasmaExtras.Menu.Open && task === (tasksRoot.toolTipOpenedByClick ?? task)
     interactive: model.IsWindow || mainItem.playerData
     hideOnClick: !(hasAudioStream && audioIndicatorsEnabled)
@@ -526,6 +554,22 @@ PlasmaCore.ToolTipArea {
         }
     }

+    // Separates tasks on different virtual desktops when sorting by desktop
+    KSvg.SvgItem {
+        // In mirrored or reversed layouts the previous task comes after this one
+        readonly property bool atEnd: task.tasksRoot.vertical ? Plasmoid.configuration.reverseMode : taskList.LayoutMirroring.enabled
+
+        visible: task.showDesktopSeparator
+
+        imagePath: "widgets/line"
+        elementId: task.tasksRoot.vertical ? "horizontal-line" : "vertical-line"
+
+        width: task.tasksRoot.vertical ? frame.width - Kirigami.Units.smallSpacing * 2 : naturalSize.width
+        height: task.tasksRoot.vertical ? naturalSize.height : frame.height - Kirigami.Units.smallSpacing * 2
+        x: task.tasksRoot.vertical ? Math.round((task.width - width) / 2) : Math.round(atEnd ? task.width + (Kirigami.Units.largeSpacing - width) / 2 : -(Kirigami.Units.largeSpacing + width) / 2)
+        y: task.tasksRoot.vertical ? Math.round(atEnd ? task.height + (Kirigami.Units.largeSpacing - height) / 2 : -(Kirigami.Units.largeSpacing + height) / 2) : Math.round((task.height - height) / 2)
+    }
+
     Loader {
         id: taskProgressOverlayLoader

-- 
